define({"topics":[{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_7.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e60481","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_6.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e60583","topics":[]},{"title":"Removing the right hand lower access panel","shortdesc":"<p class=\"shortdesc\">Removes the right-hand lower access panel from the magnet front cover.<\/p>","href":"Rep_t_RemovingTheRightHandLowerAccessPanel.html","attributes":{"data-id":"id_2008054"},"menu":{"hasChildren":false},"tocID":"id_2008054-d46e60685","topics":[]},{"title":"Removing the table interface cover","shortdesc":"<p class=\"shortdesc\">Removes the fixed or dockable table interface cover from the magnet front cover.<\/p>","href":"t_RemovingTheFixedTableInterfaceCover_3.html","attributes":{"data-id":"id_2002927"},"menu":{"hasChildren":false},"tocID":"id_2002927-d46e60787","topics":[]},{"title":"Removing the magnet left-hand lower front cover","shortdesc":"<p class=\"shortdesc\">Removes the lower cover from the left-hand front corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandLowerFrontCover.html","attributes":{"data-id":"id_2002997"},"menu":{"hasChildren":false},"tocID":"id_2002997-d46e60889","topics":[]}]});